 64→export function parseArgs(argv) {
 65→  const out = {};
 66→  for (const a of argv) {
 67→    const m = a.match(/^--([^=]+)=(.*)$/);
 68→    if (m) out[m[1]] = m[2]; else if (a.startsWith("--")) out[a.slice(2)] = true;
 69→  }
 70→  return out;
