 73→export function identityOf(letter) {
 74→  const ids = JSON.parse(readFileSync(resolve(REPO, "evaluation/tasks/identities.json"), "utf8"));
 75→  const id = ids.identities?.[letter];
 76→  if (!id) throw new Error(`identity ${letter} not in evaluation/tasks/identities.json`);
 77→  const key = readFileSync(resolve(REPO, id.key_file), "utf8").replace(/\s+/g, "");
 78→  return { letter, ...id, key };
