 87→  const text = await res.text();
 88→  let json; try { json = JSON.parse(text); } catch { throw new Error(`${path}: non-JSON ${res.status}: ${text.slice(0, 200)}`); }
 89→  if (json.code !== 0) throw new Error(`${path}: code ${json.code} ${json.message ?? ""}`);
 90→  return json.data ?? {};
