import { Buffer } from "node:buffer";

export async function fetchResource({ skillId, path, bridgeBase, fetcher = globalThis.fetch }) {
  const impl = fetcher ?? globalThis.fetch;
  if (typeof impl !== "function") throw new Error("fetchResource: no fetch implementation (pass fetcher or provide globalThis.fetch)");
  const url = `${String(bridgeBase).replace(/\/+$/, "")}/files/download`;
  const res = await impl(url, {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify({ skill_id: skillId, path, encoding: "base64" }),
  });
  const bytes = Buffer.from(await res.arrayBuffer());
  const contentType = res.headers?.get?.("content-type") ?? "";
  const looksJson = /json/i.test(contentType);
  if (!looksJson) return bytes;  // raw resource bytes
  // envelope
