    if (env.code !== 0) throw new Error(`fetchResource: ${env.message ?? `upstream code ${env.code}`}`);
    const { content, encoding } = env.data ?? {};
    if (typeof content !== "string") throw new Error(`fetchResource: ${path}: success envelope has no string content`);
