188→if (import.meta.url === `file://${process.argv[1]}`) {
189→  const args = process.argv.slice(2);
190→  const files = args.filter((a) => !a.startsWith("--"));
191→  const decoyArg = args.find((a) => a.startsWith("--decoys="));
192→  if (files.length === 0) {
